def sonar_bill(requests, in_rate, out_rate, search_fees):
    token_usd = 0.0
    search_usd = 0.0
    for req in requests:
        token_usd += (req["in_tokens"] * in_rate + req["out_tokens"] * out_rate) / 1e6
        search_usd += search_fees[req.get("context_size", "medium")]
    total = token_usd + search_usd
    return {
        "token_usd": token_usd,
        "search_usd": search_usd,
        "usd": total,
        "search_share": (search_usd / total) if total else 0.0,
    }
